-- Orientation uses a client sentinel rather than occupying a multiplayer slot.
CREATE TABLE onboarding_presence (
    player INTEGER PRIMARY KEY REFERENCES local_account(id) ON DELETE CASCADE,
    expires INTEGER NOT NULL
);
CREATE INDEX onboarding_expiry ON onboarding_presence(expires);
